const existingRows = $input.all().map(item => item.json);
const incomingJobs = $('Get Jobs Dataset').all().map(item => item.json);

// Index existing jobs by their URL
const existing = new Map();

for (const row of existingRows) {
  const link = String(row.Link || '').trim();
  if (link) existing.set(link, row);
}

// Today's date in Pacific time
const parts = Object.fromEntries(
  new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/Los_Angeles',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(new Date())
    .map(p => [p.type, p.value])
);

const today = `${parts.year}-${parts.month}-${parts.day}`;
const runId = String($execution.id || 'manual-test');

const seen = new Set();
const results = [];

for (const job of incomingJobs) {
  const link = String(job.jobUrl || '').trim();

  if (!link || seen.has(link)) continue;
  seen.add(link);

  const previous = existing.get(link);

  results.push({
    json: {
      ...job,
      'First Seen At': previous
        ? String(previous['First Seen At'] || '')
        : today,
      'First Seen Run ID': previous
        ? String(previous['First Seen Run ID'] || '')
        : runId
    }
  });
}

return results;

const jobs = $('Grab additional pending rating Rows').all();
const ratings = $('Rate pending Jobs').all();

const dashboard = 'https://script.google.com/macros/s/DEPLOYMENT_ID/exec';

const messages = [];
let message = `📋 Job Search Update\n${jobs.length} jobs rated\n\n`;

for (let i = 0; i < jobs.length; i++) {
  const job = jobs[i].json;

  const rating = ratings[i]?.json
    ?.output?.[0]?.content?.[0]?.text?.score ?? 'Pending';

  const url = dashboard + '?job=' + encodeURIComponent(job.Link);
  const escapeHtml = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const dashboardLink = `<a href="${escapeHtml(url)}">Open dashboard</a>`;

  const description = String(job['Job Description'] || '')
    .replace(/\s+/g, ' ')
    .slice(0, 150);

  const entry =
    `${escapeHtml(job.Title || 'Untitled job')}\n` +
    `${escapeHtml(job['Company Name'] || '')} · ${escapeHtml(job.Type || 'Not specified')}\n` +
    `Rating: ${rating}/100\n` +
    `${escapeHtml(description)}\n` +
    `Dashboard: ${dashboardLink}\n\n`;

  if (message.length + entry.length > 3500) {
    messages.push(message);
    message = '📋 Job Search Update (continued)\n\n';
  }

  message += entry;
}

messages.push(message);

return messages.map(text => ({
  json: { telegramText: text }
}));

