const today = `${parts.year}-${parts.month}-${parts.day}`;

// Find jobs first discovered today
const todayJobs = jobs.filter(job =>
  String(job['First Seen At'] || '').trim() === today
);

// Escape HTML to prevent formatting issues
const escape = value => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

// Format job types consistently
const formatJobType = value => {
  if (!value) return 'Not specified';

  const types = Array.isArray(value)
    ? value
    : String(value)
        .replace(/^\[|\]$/g, '')
        .replace(/["']/g, '')
        .split(',');

  const names = {
    fulltime: 'Full-time',
    'full-time': 'Full-time',
    full_time: 'Full-time',
    'full time': 'Full-time',
    parttime: 'Part-time',
    'part-time': 'Part-time',
    part_time: 'Part-time',
    'part time': 'Part-time',
    contract: 'Contract',
    contractor: 'Contract',
    temporary: 'Temporary',
    internship: 'Internship',
    intern: 'Internship',
    permanent: 'Permanent'
  };

  return types
    .map(type => {
      const cleaned = String(type).trim().toLowerCase();
      return names[cleaned] || String(type).trim();
    })
    .filter(Boolean)
    .join(', ') || 'Not specified';
};

// Sort by highest rating first
todayJobs.sort((a, b) =>
  (Number(b.Rating) || 0) - (Number(a.Rating) || 0)
);

// Build table rows
const rows = todayJobs.map(job => {
  const url = dashboard +
    '?job=' + encodeURIComponent(String(job.Link || ''));

  const rating =
    job.Rating === '' || job.Rating == null
      ? 'Pending'
      : String(job.Rating).trim();

  return `
    <tr>
      <td style="padding:10px;border:1px solid #ddd">
        ${escape(job.Title || 'Untitled job')}
      </td>
      <td style="padding:10px;border:1px solid #ddd">
        ${escape(job['Company Name'] || 'Unknown')}
      </td>
      <td style="padding:10px;border:1px solid #ddd">
        ${escape(formatJobType(job.Type))}
      </td>
      <td style="padding:10px;border:1px solid #ddd;text-align:center">
        ${escape(rating)}
      </td>
      <td style="padding:10px;border:1px solid #ddd">
        <a href="${escape(url)}"
           style="color:#2563eb;text-decoration:none">
          View Job
        </a>
      </td>
    </tr>`;
}).join('');

// Build the HTML table
const table = todayJobs.length
  ? `
    <table style="
      width:100%;
      border-collapse:collapse;
      font-family:Arial,sans-serif;
      font-size:13px;
    ">
      <thead>
        <tr style="background:#eef2f6">
          <th style="padding:10px;border:1px solid #ddd;text-align:left">
            Job Title
          </th>
          <th style="padding:10px;border:1px solid #ddd;text-align:left">
            Company
          </th>
          <th style="padding:10px;border:1px solid #ddd;text-align:left">
            Job Type
          </th>
          <th style="padding:10px;border:1px solid #ddd;text-align:center">
            Rating
          </th>
          <th style="padding:10px;border:1px solid #ddd;text-align:left">
            Dashboard
          </th>
        </tr>
      </thead>
      <tbody>${rows}</tbody>
    </table>`
  : '<p>No new jobs were discovered today.</p>';

// Build email
const emailHtml = `
  <div style="
    font-family:Arial,sans-serif;
    color:#243247;
    line-height:1.5;
  ">
    <h2>Daily Job Search Summary</h2>

    <p>Good evening,</p>

    <p>
      Here is your daily job search summary
      for <strong>${today}</strong>.
    </p>

    <p>
      <strong>${todayJobs.length}</strong>
      new jobs discovered today.
    </p>

    ${table}

    <p style="
      margin-top:24px;
      color:#777;
      font-size:12px;
    ">
      Generated automatically by your job search workflow.
    </p>
  </div>
`;

return [{
  json: {
    subject: `Daily Job Summary - ${today} (${todayJobs.length} jobs)`,
    emailHtml,
    jobCount: todayJobs.length
  }
}];

